using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns information about an invite link. Requires administrator privileges and can_invite_users right in the chat to get own links and owner privileges to get other links
    /// </summary>
    public Task<TdLib.TdApi.Objects.ChatInviteLink> GetChatInviteLinkAsync(long chatId = default, string inviteLink = default)
    {

           using var activity =  StartCallActivity("GetChatInviteLinkAsync", typeof(GetChatInviteLink).FullName ?? "GetChatInviteLinkAsync");

           try
           {
             return client.GetChatInviteLinkAsync(chatId, inviteLink);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
